using System.Diagnostics;
namespace WinUser;
public sealed partial class MainForm
{
    Label? accountSelectionHint;
    void BuildAccountsPage(TabControl tabs)
    {
        var page=Page(tabs,"Quản lý User / RDP");
        var body=new FlowLayoutPanel(){Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(6)};
        var general=Bar();general.Dock=DockStyle.None;general.Controls.AddRange(new Control[]{Button("＋ Tạo user",CreateUser),Button("Quản lý Windows…",()=>Process.Start(new ProcessStartInfo("lusrmgr.msc"){UseShellExecute=true}))});body.Controls.Add(general);
        accountSelectionHint=new Label(){AutoSize=true,MaximumSize=new System.Drawing.Size(550,0),Padding=new Padding(8)};body.Controls.Add(accountSelectionHint);
        body.Controls.Add(AccountGroup("Thông tin tài khoản",TargetButton("Sửa / Chi tiết",EditAccount,true),TargetButton("Đổi tên",RenameAccount,true),TargetButton("Đổi mật khẩu",ChangePassword,true),TargetButton("Nhóm cục bộ",EditMembership,true),TargetButton("Xóa user",DeleteAccount,true)));
        body.Controls.Add(AccountGroup("Truy cập tài khoản",TargetButton("Khóa tài khoản",()=>Batch("Khóa tài khoản + ngắt phiên RDP",u=>WindowsAccounts.Enabled(u,false))),TargetButton("Mở tài khoản",()=>Batch("Bật tài khoản",u=>WindowsAccounts.Enabled(u,true))),TargetButton("Gỡ khóa sai mật khẩu",()=>Batch("Gỡ lockout",WindowsAccounts.Unlock))));
        body.Controls.Add(AccountGroup("RDP & phiên",TargetButton("Mở RDP",()=>Batch("Mở RDP: cấp nhóm và bỏ Deny trực tiếp",u=>WindowsAccounts.Rdp(u,true))),TargetButton("Đóng RDP",()=>Batch("Đóng RDP: đặt Deny trực tiếp và gỡ nhóm",u=>WindowsAccounts.Rdp(u,false))),TargetButton("Ngắt phiên",()=>Batch("Ngắt phiên RDP, giữ chương trình đang chạy",WindowsAccounts.Disconnect))));
        body.Controls.Add(new Label(){AutoSize=true,MaximumSize=new System.Drawing.Size(550,0),Padding=new Padding(8),ForeColor=System.Drawing.Color.DarkSlateGray,Text="RDP: Mở* = đã cấp nhóm, bỏ Deny trực tiếp; Đóng = Deny trực tiếp; Chưa cấp = chưa cấp nhóm. Quyền đăng nhập còn phụ thuộc Windows/GPO.\r\nKhóa tài khoản sẽ ngắt phiên RDP, không đăng xuất. Đổi tên giữ SID/profile; xóa user giữ dữ liệu."});page.Controls.Add(body);
        body.SizeChanged+=(_,_)=>{foreach(var label in body.Controls.OfType<Label>())label.MaximumSize=new System.Drawing.Size(Math.Max(210,body.ClientSize.Width-40),0);foreach(var group in body.Controls.OfType<GroupBox>()){var width=Math.Max(240,body.ClientSize.Width-40);group.MaximumSize=new System.Drawing.Size(width,0);group.MinimumSize=new System.Drawing.Size(width,0);((FlowLayoutPanel)group.Controls[0]).MaximumSize=new System.Drawing.Size(Math.Max(210,width-25),0);}};
    }
    void CreateUser(){using var d=new Form(){Text="Tạo tài khoản Windows local",Width=440,Height=275,StartPosition=FormStartPosition.CenterParent};var panel=Bar();var name=new TextBox(){Width=250};var password=new TextBox(){Width=250,UseSystemPasswordChar=true};var apply=new CheckBox(){Text="Áp dụng bộ đang chọn sau khi tạo",AutoSize=true};panel.Controls.AddRange(new Control[]{new Label(){Text="Tên user:",AutoSize=true},name,new Label(){Text="Mật khẩu:",AutoSize=true},password,apply});var ok=new Button(){Text="Tạo",DialogResult=DialogResult.OK};panel.Controls.Add(ok);d.Controls.Add(panel);d.AcceptButton=ok;if(d.ShowDialog(this)!=DialogResult.OK)return;var n=Policy.UserName(name.Text);var p=apply.Checked?Preset():null;if(!Confirm("Tạo user thường: "+n+" (không cấp Administrator)."+(p==null?"":"\r\n"+PresetPreview(p))))return;WindowsAccounts.Create(n,password.Text);password.Clear();var user=WindowsAccounts.List().Single(u=>u.Name.Equals(n,StringComparison.OrdinalIgnoreCase));Storage.Log("CreateUser",user.Sid,true);Append("Đã tạo "+n);RefreshUsers();if(p!=null){try{Presets.Apply(p,user);Append("Đã áp dụng cấu hình.");}catch{Append("User đã tạo; áp dụng cấu hình chưa hoàn tất.");throw;}}}
    void EditAccount()
    {
        var u=SingleTarget();var info=WindowsAccounts.Details(u);using var dialog=new Form(){Text="Thông tin: "+u.Name,Width=560,Height=450,StartPosition=FormStartPosition.CenterParent};var panel=Bar();
        var full=new TextBox(){Width=440,Text=info.FullName};var desc=new TextBox(){Width=440,Text=info.Description};var never=new CheckBox(){Text="Mật khẩu không hết hạn",Checked=(info.Flags&0x10000)!=0,AutoSize=true};
        panel.Controls.AddRange(new Control[]{new Label(){Text=u.Sid+"\r\n"+u.AccountStatus+" | "+u.SessionStatus+"\r\nNhóm: "+string.Join(", ",info.Groups),Width=480,Height=90},new Label(){Text="Tên đầy đủ",AutoSize=true},full,new Label(){Text="Mô tả",AutoSize=true},desc,never,Button("Lưu",()=>{WindowsAccounts.Edit(u,full.Text,desc.Text,never.Checked);Storage.Log("EditAccount",u.Sid,true);dialog.Close();RefreshUsers();})});dialog.Controls.Add(panel);dialog.ShowDialog(this);
    }
    void RenameAccount(){var u=SingleTarget();var name=Prompt("Đổi tên user (giữ SID và đường dẫn profile)",u.Name);if(name==null||!Confirm("Đổi "+u.Name+" → "+name+"? Các chương trình dùng tên cũ có thể cần cập nhật."))return;WindowsAccounts.Rename(u,name);Storage.Log("RenameUser",u.Sid,true);RefreshUsers();RefreshNas();}
    void ChangePassword()
    {
        var u=SingleTarget();using var d=new Form(){Text="Đặt lại mật khẩu: "+u.Name,Width=510,Height=285,StartPosition=FormStartPosition.CenterParent};var panel=Bar();var a=new TextBox(){Width=430,UseSystemPasswordChar=true,PlaceholderText="Mật khẩu mới"};var b=new TextBox(){Width=430,UseSystemPasswordChar=true,PlaceholderText="Nhập lại mật khẩu"};panel.Controls.AddRange(new Control[]{new Label(){Text="Đặt lại bởi admin có thể làm mất quyền đọc EFS, chứng chỉ và bí mật DPAPI cũ. Không đọc hoặc hiển thị mật khẩu hiện tại.",Width=450,Height=65},a,b,Button("Đặt lại",()=>{if(a.Text!=b.Text)throw new ArgumentException("Hai mật khẩu không khớp.");if(!Confirm("Đặt lại mật khẩu cho "+u.Name+"? Đã kiểm tra dữ liệu EFS/DPAPI của user?"))return;WindowsAccounts.Password(u,a.Text);a.Clear();b.Clear();Storage.Log("ResetPassword",u.Sid,true);d.Close();})});d.Controls.Add(panel);d.ShowDialog(this);
    }
    void DeleteAccount(){var u=SingleTarget();if(Prompt("Gõ đúng tên user để xóa tài khoản; GIỮ profile/tệp")!=u.Name)return;if(!Confirm("Xóa tài khoản "+u.Name+" và cấu hình NAS của SID này? Không thể khôi phục SID bằng cách tạo lại cùng tên."))return;WindowsAccounts.Delete(u);Storage.Log("DeleteUser",u.Sid,true);RefreshUsers();RefreshNas();}
    void EditMembership(){var u=SingleTarget();var info=WindowsAccounts.Details(u);var group=Prompt("Nhóm hiện tại: "+string.Join(", ",info.Groups)+". Nhập tên nhóm cục bộ:");if(string.IsNullOrWhiteSpace(group))return;var choice=MessageBox.Show("Thêm "+u.Name+" vào "+group+"?\r\nCó = Thêm; Không = Gỡ; Hủy = Dừng.","Nhóm cục bộ",MessageBoxButtons.YesNoCancel);if(choice==DialogResult.Cancel)return;WindowsAccounts.Membership(u,group,choice==DialogResult.Yes);Storage.Log("GroupMembership",u.Sid,true);RefreshUsers();}
}
